        out.push('0');
    } else if (1e-6..1e21).contains(&f.abs()) {
        let _ = write!(out, "{f}");
    } else {
        let start = out.len();
        let _ = write!(out, "{f:e}");
        if let Some(e) = out[start..].find('e') {
            let after = start + e + 1;
            if !out[after..].starts_with('-') {
                out.insert(after, '+');
            }
        }
    }
}

