impl<K: Clone, E: Clone> Clone for GraphBuilder<K, E> {
    /// A copy with its own identity: declarations made on either builder after the clone don't work on the other.
    fn clone(&self) -> Self {
        let mut ancestors = self.ancestors.clone();
