                self.ready.insert(i);
            } else {
                self.remaining[i] = waiting;
            }
        }
    }

    async fn drive(&mut self) {
        let cap = match self.opts.mode {
            Mode::Sequential => 1,
            Mode::Parallel { max_concurrency } => max_concurrency.get(),
        };
