//! The per-run record: what happened to every step, and the overall outcome.

use std::time::Duration;

use michi_core::pipeline::{Pipeline, PipelineStep, StepStatus};

use crate::{Effect, ExecutionError, Plan, PlanFingerprint, Replay, ReplayClass, ResumeError, RunId, StepId};

/// One attempt of one step.
#[derive(Debug, Clone, PartialEq)]
#[cfg_attr(feature = "serde", derive(serde::Serialize, serde::Deserialize))]
pub struct AttemptRecord {
    pub(crate) attempt: u32,
    pub(crate) class: Option<ReplayClass>,
    pub(crate) error: Option<String>,
    pub(crate) elapsed: Duration,
}

impl AttemptRecord {
    /// 0-based attempt number.
    #[must_use]
    pub fn attempt(&self) -> u32 {
        self.attempt
    }

    /// The replay class of the attempt's failure, or `None` if it succeeded.
    #[must_use]
    pub fn class(&self) -> Option<ReplayClass> {
        self.class
    }

    /// The attempt's error message, or `None` if it succeeded.
    #[must_use]
    pub fn error(&self) -> Option<&str> {
        self.error.as_deref()
    }

    /// How long the attempt ran.
    #[must_use]
    pub fn elapsed(&self) -> Duration {
        self.elapsed
    }
}

/// What happened to one step in one run.
#[derive(Debug, Clone, PartialEq)]
#[cfg_attr(feature = "serde", derive(serde::Serialize, serde::Deserialize))]
pub struct StepRecord {
    pub(crate) step_id: StepId,
    pub(crate) name: String,
    pub(crate) status: StepStatus,
    pub(crate) reason: Option<String>,
    pub(crate) error: Option<ExecutionError>,
    pub(crate) attempts: Vec<AttemptRecord>,
    pub(crate) started_at: Option<Duration>,
    pub(crate) elapsed: Option<Duration>,
    pub(crate) caused_by: Option<StepId>,
    /// The step's [`Replay`] when the executor or [`RunRecord::from_parts`] wrote the record; `None` in a record saved
    /// by hand (such as [`StepRecord::in_flight`]) or by an older michi-pipeline, which counts as not idempotent.
    #[cfg_attr(feature = "serde", serde(default, skip_serializing_if = "Option::is_none"))]
        /// The maximum length.
        max: usize,
    },
    /// The id contains a character outside the slug charset.
    #[error("id has {ch:?} at byte {index}; use ASCII letters, digits, '_', '-' or '.', starting with a letter, digit or '_'")]
    InvalidChar {
        /// The offending character.
        ch: char,
        /// Its byte offset.
        index: usize,
    },
}

/// Checks the slug rule shared by [`StepId`] and [`RunId`].
fn validate(s: &str) -> Result<(), IdError> {
    if s.is_empty() {
        return Err(IdError::Empty);
    }
    if s.len() > MAX_ID_LEN {
        return Err(IdError::TooLong { len: s.len(), max: MAX_ID_LEN });
    }
    for (index, ch) in s.char_indices() {
        let ok = ch.is_ascii_alphanumeric() || ch == '_' || (index > 0 && (ch == '-' || ch == '.'));
        if !ok {
            return Err(IdError::InvalidChar { ch, index });
        }
    }
    Ok(())
}

macro_rules! slug_id {
    ($(#[$doc:meta])* $name:ident) => {
        $(#[$doc])*
        #[derive(Debug, Clone, PartialEq, Eq, Hash, PartialOrd, Ord)]
        #[cfg_attr(feature = "serde", derive(serde::Serialize, serde::Deserialize))]
        #[cfg_attr(feature = "serde", serde(try_from = "String", into = "String"))]
        pub struct $name(String);

        impl $name {
            /// Validates `id` against the slug rule: 1 to 64 ASCII letters, digits, `_`, `-` or `.`, starting with a
            /// letter, digit or `_`.
            ///
            /// # Errors
            ///
            /// [`IdError::Empty`], [`IdError::TooLong`] or [`IdError::InvalidChar`] when `id` breaks the rule.
            pub fn try_new(id: impl Into<String>) -> Result<Self, IdError> {
                let id = id.into();
                validate(&id)?;
                Ok(Self(id))
            }

            /// The id as a string slice.
            #[must_use]
            pub fn as_str(&self) -> &str {
                &self.0
            }
        }

        impl fmt::Display for $name {
            fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
                f.write_str(&self.0)
            }
        }

        impl AsRef<str> for $name {
            fn as_ref(&self) -> &str {
                &self.0
            }
        }

        impl TryFrom<&str> for $name {
            type Error = IdError;
            fn try_from(id: &str) -> Result<Self, IdError> {
                Self::try_new(id)
            }
        }

        impl TryFrom<String> for $name {
            type Error = IdError;
            fn try_from(id: String) -> Result<Self, IdError> {
                Self::try_new(id)
            }
        }

        impl From<$name> for String {
            fn from(id: $name) -> String {
                id.0
            }
        }
    };
}

