use michi_core::toon::{render_toon, ToonOptions, Value};
use michi_core::{AgentResponse, OutputFormat, Section};
use std::alloc::{GlobalAlloc, Layout, System};
use std::sync::atomic::{AtomicUsize, Ordering::Relaxed};
use std::time::Instant;

struct Counting;
static ALLOCS: AtomicUsize = AtomicUsize::new(0);
static BYTES: AtomicUsize = AtomicUsize::new(0);
unsafe impl GlobalAlloc for Counting {
    unsafe fn alloc(&self, l: Layout) -> *mut u8 {
        ALLOCS.fetch_add(1, Relaxed);
        BYTES.fetch_add(l.size(), Relaxed);
        System.alloc(l)
    }
    unsafe fn dealloc(&self, p: *mut u8, l: Layout) {
        System.dealloc(p, l)
    }
    unsafe fn realloc(&self, p: *mut u8, l: Layout, n: usize) -> *mut u8 {
        ALLOCS.fetch_add(1, Relaxed);
        BYTES.fetch_add(n, Relaxed);
        System.realloc(p, l, n)
    }
}
#[global_allocator]
static A: Counting = Counting;

fn rows(n: usize) -> Vec<Vec<Value>> {
    (0..n)
        .map(|i| {
            vec![
                Value::Int(i as i64),
                Value::from(format!("Issue title number {i} with some longer descriptive text to exceed inline")),
                Value::from("open"),
            ]
        })
        .collect()
}

fn measure<R>(label: &str, iters: usize, mut f: impl FnMut() -> R) {
    let _ = f();
    let a0 = ALLOCS.load(Relaxed);
    let b0 = BYTES.load(Relaxed);
    let t = Instant::now();
    for _ in 0..iters {
        std::hint::black_box(f());
    }
    let el = t.elapsed();
    println!(
        "{label:40} {:>9.1} us/iter  {:>6} allocs/iter {:>9} bytes/iter",
        el.as_secs_f64() * 1e6 / iters as f64,
        (ALLOCS.load(Relaxed) - a0) / iters,
        (BYTES.load(Relaxed) - b0) / iters
    );
}

fn main() {
    for n in [100usize, 1000] {
        println!("--- {n} rows x 3 fields");
        let fields: Vec<String> = vec!["number".into(), "title".into(), "state".into()];
        let opts = ToonOptions::new("issue", fields.clone(), rows(n));
        measure("render_toon", 200, || render_toon(&opts).unwrap());
        let r = AgentResponse::new("issue").section(Section::toon("issue", fields.clone(), rows(n)));
        measure("AgentResponse::render Text", 200, || r.render(OutputFormat::Text));
        measure("AgentResponse::is_error", 200, || r.is_error());
        measure("AgentResponse::to_call_tool_result", 200, || r.to_call_tool_result());
        measure("AgentResponse::render Json", 200, || r.render(OutputFormat::Json));
        // typical: is_error + to_call_tool_result
        measure("is_error + to_call_tool_result", 200, || (r.is_error(), r.to_call_tool_result()));
    }
}

